    "text": "Em um texto dissertativo-argumentativo, o autor utiliza o seguinte trecho: 'O desemprego cresceu 15% no último trimestre. Consequentemente, o poder de compra da população caiu drasticamente.' O conectivo 'Consequentemente' estabelece uma relação semântico-discursiva de:",
