      "Correta. A coesão trata da superfície linguística (amarração gramatical, pronomes, conjunções), enquanto a coerência trata do plano semântico e pragmático (sentido global, não contradição, lógica). Um texto pode ter todos os conectivos formais corretos e ainda assim ser ilógico e incoerente.",
